  subheader_desc_mydeck: 'จัดการการ์ดที่คุณมี สวมใส่อุปกรณ์และทักษะพิเศษ เพื่อสร้างเด็คที่ดีที่สุดของคุณ',
  subheader_desc_ranking: 'ตรวจสอบอันดับกระดานผู้นำระดับโลกและท้าทายเหล่านักล่าผ่านโหมดการจับคู่ที่หลากหลาย',
  subheader_desc_skills: 'ใช้แต้มทักษะเพื่อปลดล็อกบัฟติดตัวถาวรและเพิ่มคุณสมบัติให้กับเด็คของคุณ',
  subheader_desc_setting: 'ปรับระดับเสียง, การตั้งค่าระบบ, การเชื่อมต่อฐานข้อมูล และกลยุทธ์การต่อสู้อัตโนมัติ',
  subheader_desc_event: 'เข้าร่วมกิจกรรมจำกัดเวลา เช่น วงล้อนำโชค และตู้คีบตุ๊กตา เพื่อรับรางวัลพิเศษ',
  subheader_desc_profile: 'ตรวจสอบรหัสนักล่าของคุณ, บันทึกการต่อสู้ และแก้ไขชื่อเล่นของคุณ',
  subheader_desc_guild_list: 'สร้างหรือเข้าร่วมกิลด์สมาคมนักล่าเพื่อร่วมมือกันทำงานกับสมาชิกคนอื่นๆ',
  subheader_desc_guild_detail: 'จัดการสมาชิก, บริจาคเงินสนับสนุนกิลด์ และจัดเตรียมแผนการบุกรุกกิลด์อื่น',
  subheader_desc_playground: 'ทดสอบการผสมผสานการ์ดและกลยุทธ์ต่างๆ ได้อย่างอิสระโดยไม่ส่งผลกระทบต่อสถิติจริงของคุณ',
  subheader_desc_admin: 'เทอร์มินัลความปลอดภัยสำหรับการตรวจสอบฐานข้อมูลระบบและการจัดการเซสชันแบบเรียลไทม์',
  subheader_desc_god: 'แซนด์บ็อกซ์สำหรับผู้พัฒนาโดยเฉพาะ ปรับเปลี่ยนทรัพยากรโดยตรงและดีบักสถานะไคลเอนต์',
  subheader_desc_companion: 'ฝึกฝน, ให้อาหาร และสร้างความผูกพันกับฮีโร่คู่หูผู้ซื่อสัตย์ที่คอยช่วยเหลือในการต่อสู้',
  subheader_desc_wiki_card: 'เรียกดูรายละเอียดคุณสมบัติและการแบ่งระดับความหายากของฮีโร่การ์ดทั้ง 110 ใบ',
  subheader_desc_wiki_howtoplay: 'เรียนรู้กฎพื้นฐานและกลยุทธ์การชนะสำหรับการต่อสู้การ์ดในตาราง 3x3',
  subheader_desc_wiki_item: 'สำรวจคุณสมบัติของสร้อยคอ, แหวน และรองเท้าบูทที่ฮีโร่สามารถสวมใส่ได้',
  subheader_desc_wiki_skill: 'ตรวจสอบทักษะที่กดใช้งาน, บัฟติดตัว และเลเวลที่กำหนดสำหรับผังทักษะ',
