    mode_slide2048_guide: 'เลื่อนแผ่นตัวเลขเพื่อรวมกัน!\nรวมตัวเลขที่เหมือนกันเพื่อให้ได้ 2048\nใช้ปุ่มลูกศรหรือปัดเพื่อเล่น\nรับรางวัล SNS ตามคะแนนของคุณ!',
