    mode_cardheist: 'ปล้นการ์ด',
    mode_cardheist_guide: 'ย่องผ่านการ์ดศัตรูเพื่อขโมยสมบัติ!\nเลื่อนหรือใช้ปุ่มลูกศรเพื่อนำทางในตาราง\nหลบศัตรูที่ลาดตระเวนและเก็บการ์ดสมบัติทั้งหมด\nผ่านทุกระดับเพื่อรับรางวัล SNS!',

    mode_cardtap: 'แตะการ์ด',
