    mode_cardslide_guide: 'ปัดไทล์ไปยังช่องว่าง!\nจัดเรียงรูปการ์ดให้ถูกต้องเพื่อชนะ\nยิ่งใช้การเคลื่อนไหวน้อย = รางวัล SNS มากขึ้น!',

    mode_cardslot: 'สล็อตการ์ด',
    mode_cardslot_guide: 'สล็อตแมชชีนการ์ดคลาสสิก 3x3!\nหมุนวงล้อและจับคู่การ์ด 3 ใบในแถวหรือแนวทแยง\nการ์ดเด็คของคุณปรากฏเป็นสัญลักษณ์ WILD ที่ตรงกับทุกอย่าง!\n5 เส้นการจ่ายเงิน — การจับคู่ที่ใหญ่กว่าได้รับ SNS มากขึ้น!',
    mode_cardsorcery: 'เวทมนตร์การ์ด',
    mode_cardsorcery_guide: 'ใช้การแพ้ชนะทางธาตุเพื่อเอาชนะการ์ดศัตรูที่กำลังเข้ามา!\nวัฏจักรการชนะทาง: น้ำ > ไฟ > ลม > ดิน > น้ำ\nจับคู่ธาตุที่ชนะทางเพื่อให้ได้คะแนนสูง!\nรักษาคอมโบภายในเวลาที่กำหนดเพื่อรับรางวัล SNS ที่มากขึ้น!',
