    ip_card_9_origin: 'Octopus is a key character of the Water faction, holding a a legendary figure who commands pure awe and shakes the battlefield as a golden Gold card status. Optimized for tactical positioning with a strong emphasis on South direction (stat value of 10), they provide a balanced combat power (CP) of 26 to support the frontline. Benefiting from the unique COUNTER ability, they excel at Rebound: If an enemy fails to flip this card, they are captured instead during combat. They stand as a reliable companion representing their faction\'s core values.',
