    ip_card_10_origin: 'Poseidon, the god who rules the primordial sea. With a single thrust of his legendary trident, he summons catastrophic tsunamis, swallowing whole battalions of foes in raging waves. His absolute throne lies in the deepest, most quiet marine trench, from which he commands every water spirit in existence.',
