    ip_card_20_origin: 'An immortal born from the colossal flare of a dying star, Ignisius burns hotter than ten-thousand suns. His massive claymore swings melt mountain ranges in a blink. Legend says he bloomed from the final spark of the first star in the cosmos, inheriting its eternal light and destructive fire.',
    ip_card_20_growth: 'The blazing growth arc of Ignisius. Breaking the ancient cosmic seals binding his solar core, he masters the white-hot flame of destruction that governs the rules of the cosmos.',
