    ip_card_30_origin: 'The wind god Thor, who commands thunder and lightning with raw authority. Every swing of his legendary hammer, Mjölnir, splits the heavens and conjures relentless storms that tear enemy ranks apart. He stands as the stalwart guardian of Asgard, silently preparing for the promised final battlefield.',
    ip_card_30_growth: 'The intense training arc of Thor. Standing in the eye of a global tempest, he channels high-voltage lightning into Mjölnir, perfecting his sync with the hammer to become the storm.',
    ip_card_30_line: '"When the sky cracks and the storm howls, know that I have arrived. No shield or fortress shall remain standing under the strike of my hammer!"',
    ip_card_30_webtoon_hook: 'Thor: The storm god descends with thunderous rage. Witness the raw power of Mjölnir splitting the skies in this dramatic saga!',
