    ip_card_40_origin: 'A titan awakened from the heart of the earth. One step shakes continents; one punch topples fortresses. He lay dormant for millennia, but rises anew with furious tectonic energy whenever war poisons the soil.',
    ip_card_40_growth: 'The colossal awakening of Colossus. Absorbing the deep crystalline essence of the earth, he reinforces his heavy stone armor to stand firm against any crowd control or combos.',
    ip_card_40_line: '"I am the earth beneath your feet. Your petty tricks and schemes shall not move me even a single inch!"',
