    webtoon_s1_title: 'ยุคแห่งการปะทะ',
    webtoon_s1_description: 'การตื่นขึ้นของทั้ง 11 กองทัพ และความขัดแย้งเหนือ SNS Core ท่ามกลางความโกลาหลที่เริ่มจากไฟกับน้ำ ใครๆ ก็เป็นฮีโร่ได้หรือไม่?',
    webtoon_s1_e01_title: 'ตอนที่ 1: เสียงเรียกจากห้วงลึก',
    webtoon_s1_e01_logline: 'ณ จุดลึกที่สุดของห้วงเหวอควา โพไซดอน เทพแห่งท้องทะเลตื่นขึ้น การกระทำแรกของเขาหลังหลับไหลนับพันปีคืออะไร?',
    webtoon_s1_e01_conflict: 'รอยแยกแห่งห้วงลึก — การตื่นขึ้นของโพไซดอนและการล่มสลายของระบบนิเวศใต้ทะเล',
    webtoon_s1_e01_p01_caption: 'ห้วงเหวอควา — ชั่วขณะที่ความเงียบงันนับพันปีถูกทำลาย',
    webtoon_s1_e01_p02_caption: 'เทพแห่งท้องทะเลลืมตาขึ้น',
    webtoon_s1_e01_p03_caption: 'รอยแยกแห่งห้วงลึก — แสงสีแดงลอดออกมา',
    webtoon_s1_e01_p04_caption: 'สภาลับของอ็อกโทปัสกับจ้าววารี',
    webtoon_s1_e01_p05_caption: 'โพไซดอนยกตรีศูล — เปลวไฟเหนือรอยแยก',
    webtoon_s1_e01_p06_caption: '"ด้วยนามแห่งท้องทะเล... ข้าขอประกาศสงคราม"',
    webtoon_s1_e02_title: 'ตอนที่ 2: กำเนิดลุกโชน',
    webtoon_s1_e02_logline: 'อิกนิซิอัสกำเนิดจากใจกลางสุริยา ราชันย์แห่งอัคคีตามหาเทพแห่งท้องทะเลไปทำไม?',
    webtoon_s1_e02_conflict: 'ไฟปะทะน้ำ — การเผชิญหน้าครั้งแรกของเทพธาตุทั้งสอง',
    webtoon_s1_e02_p01_caption: 'ใจกลางสุริยา — กำเนิดอิกนิซิอัส',
    webtoon_s1_e02_p02_caption: 'ฟีนิกซ์นำทาง — ชั่วขณะแห่งย่างก้าวแรก',
    webtoon_s1_e02_p03_caption: 'ราชสำนักอัคคี — รายงานความผิดปกติ',
